import type { Metadata, Viewport } from "next";
import { Geist_Mono } from "next/font/google";
import localFont from "next/font/local";
import Seasons from "@/components/Seasons";
import { author, projects, site } from "@/lib/site";
import "./globals.css";

const mono = Geist_Mono({
  subsets: ["latin"],
  variable: "--font-mono",
  display: "swap",
});

/* Nexor Grid: the site's own face, generated by scripts/nexor-grid/build.py.
   One weight; declared as a range so canvas never synthesises bold. */
const display = localFont({
  src: "./fonts/NexorGrid.woff",
  variable: "--font-display",
  weight: "100 900",
  display: "block",
  fallback: ["monospace"],
});

export const metadata: Metadata = {
  metadataBase: new URL(site.url),
  title: {
    default: site.title,
    template: `%s / ${site.domain}`,
  },
  description: site.description,
  applicationName: site.domain,
  authors: [{ name: author, url: site.github }],
  creator: author,
  publisher: author,
  keywords: [...site.keywords, ...projects.map((p) => p.name)],
  category: "technology",
  alternates: { canonical: "/" },
  openGraph: {
    type: "website",
    url: site.url,
    title: site.title,
    description: site.description,
    siteName: site.domain,
    locale: "en_US",
  },
  twitter: {
    card: "summary_large_image",
    title: site.title,
    description: site.description,
  },
  robots: {
    index: true,
    follow: true,
    googleBot: { index: true, follow: true, "max-image-preview": "large", "max-snippet": -1 },
  },
  verification: process.env.GOOGLE_SITE_VERIFICATION
    ? { google: process.env.GOOGLE_SITE_VERIFICATION }
    : undefined,
  formatDetection: { telephone: false, email: false, address: false },
};

export const viewport: Viewport = {
  themeColor: site.colors.bg,
  colorScheme: "dark",
  width: "device-width",
  initialScale: 1,
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${mono.variable} ${display.variable}`} suppressHydrationWarning>
      <body>
        <a className="skip" href="#work">
          Skip to the projects
        </a>
        {children}
        <Seasons />
      </body>
    </html>
  );
}
